 */
function filterUsersByExampleDomain_compatible(array $users): array
{
    $domain = '@example.com';
    $domainLength = strlen($domain);

    $filtered = array_filter($users, function ($user) use ($domain, $domainLength) {
        // Check if email key exists and is long enough
        if (!isset($user['email']) || strlen($user['email']) < $domainLength) {
            return false;
        }

        // Get the end of the email string and compare it to the domain
        return substr($user['email'], -$domainLength) === $domain;
    });

    return array_values($filtered);
}


